"""Individual primary-source decisions; no inferred author commands or editions.

Indices refer to the frozen, hashed primary XML paragraph population. Edition
labels describe their cited stage, including methodological references. They
are never substituted for the selected current project runtime. Component
overlap is partial and does not establish a complete executable author recipe.
"""


def edition(literal, indices, context, pdf_pages=None):
    result = dict(literal=literal, paragraph_indices=indices, context=context)
    if pdf_pages is not None:
        result['pdf_pages'] = pdf_pages
    return result


def role(indices, editions, kind, summary, caution, overlap, remaining):
    return dict(paragraph_indices=indices, reported_editions=editions, role=kind,
                use_summary=summary, required_caution=caution,
                qualified_component_overlap=overlap, remaining_roles=remaining)


